// ===== CONFIGURACIÓN DEL FLUJO =====
// Lo único que normalmente se cambia. Los demás nodos leen estos valores.
return [{
  json: {
    // Dónde está la app. Prueba en tu PC: http://host.docker.internal:8000
    // En el VPS: https://hadmind.com.co
    url_app: 'http://host.docker.internal:8000',
    correo: 'hadmind@gmail.com',
    // Modelos de OpenAI (cámbialos si tu cuenta usa otros)
    modelo_texto: 'gpt-5-mini',
    modelo_imagen: 'gpt-image-1',
    calidad_imagen: 'medium',          // low | medium | high (más alta = más cara)
    dias: 8,                           // antigüedad máxima de las noticias
    feeds: [
      'https://www.xataka.com/feedburner.xml',
      'https://hipertextual.com/feed',
      'https://wwwhatsnew.com/feed/',
      'https://www.enter.co/feed/',
      'https://impactotic.co/feed/',
      'https://www.portafolio.co/rss/tecnologia.xml',
    ],
    // Nombre bonito del medio para "Fuente:" (por dominio)
    medios: {
      'xataka.com': 'Xataka',
      'hipertextual.com': 'Hipertextual',
      'wwwhatsnew.com': "WWWhat's new",
      'enter.co': 'ENTER.CO',
      'impactotic.co': 'Impacto TIC',
      'portafolio.co': 'Portafolio',
    },
    // Parte FIJA del prompt de imagen: el estilo HADMIND. La IA solo añade la escena.
    estilo_imagen:
      'Editorial illustration for a technology blog aimed at small businesses. ' +
      'Clean, modern, minimal style mixing soft 3D and flat shapes, soft lighting, generous negative space. ' +
      'Brand palette: blue #3E83D6, darker blue #2F6DB8, deep navy #020617, white and light blue #EEF4FC accents. ' +
      'No text, no letters, no numbers, no logos, no brand names, no watermarks, no recognizable real people. ' +
      'Horizontal composition with the subject centered so it can be cropped to 16:10.',
  },
}];

// Lee el XML de cada feed, junta las noticias, quita las viejas y las ya
// usadas (también las descartadas) y prepara la pregunta para que la IA elija.
const cfg = $('Configuración').first().json;

const entidades = { '&nbsp;': ' ', '&amp;': '&', '&quot;': '"', '&apos;': "'", '&lt;': '<', '&gt;': '>',
  '&rsquo;': '’', '&lsquo;': '‘', '&ldquo;': '“', '&rdquo;': '”', '&ndash;': '–', '&mdash;': '—', '&hellip;': '…' };
const decodificar = (t) => t
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
  .replace(/&[a-z]+;/gi, (e) => entidades[e] || e);
// Quita CDATA y etiquetas HTML (la descripción a veces trae HTML escapado)
const limpiar = (t) => decodificar(decodificar(t.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1'))
  .replace(/<[^>]+>/g, ' ')).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const etiqueta = (xml, nombre) => {
  const m = xml.match(new RegExp('<' + nombre + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + nombre + '>', 'i'));
  return m ? limpiar(m[1]) : '';
};

// Sin new URL(): el código de n8n corre aislado y ahí URL no existe.
// Misma noticia aunque traiga ?utm=... o #seccion
const normalizar = (url) => String(url || '').trim().split('#')[0].split('?')[0].replace(/\/$/, '').toLowerCase();

function medio(url) {
  const m = String(url || '').match(/^https?:\/\/(?:www\.)?([^\/:?#]+)/i);
  const dominio = m ? m[1].toLowerCase() : '';
  return cfg.medios[dominio] || dominio;
}

const usadas = new Set(($('Fuentes usadas').first().json.fuentes || []).map(normalizar));
const limite = Date.now() - cfg.dias * 24 * 60 * 60 * 1000;
const vistas = new Set();
const candidatas = [];

const noticias = [];
for (const feed of $input.all()) {
  const xml = typeof feed.json.data === 'string' ? feed.json.data : '';
  // Un feed caído llega sin "data" y se salta: no detiene el flujo
  for (const bloque of xml.match(/<item[\s>][\s\S]*?<\/item>/gi) || []) {
    noticias.push({
      titulo: etiqueta(bloque, 'title'),
      link: etiqueta(bloque, 'link'),
      fecha: new Date(etiqueta(bloque, 'pubDate') || etiqueta(bloque, 'dc:date') || 0).getTime(),
      resumen: etiqueta(bloque, 'description').slice(0, 300),
    });
  }
}

for (const n of noticias) {
  if (!n.link || !n.titulo || !n.fecha || n.fecha < limite) continue;
  const clave = normalizar(n.link);
  if (usadas.has(clave) || vistas.has(clave)) continue;
  vistas.add(clave);
  candidatas.push({ titulo: n.titulo, url: n.link, medio: medio(n.link), fecha: n.fecha, resumen: n.resumen });
}

// Máximo 8 por medio: Xataka publica muchísimo y taparía a los demás
candidatas.sort((a, b) => b.fecha - a.fecha);
const porMedio = {};
const lista = candidatas.filter((c) => (porMedio[c.medio] = (porMedio[c.medio] || 0) + 1) <= 8).slice(0, 48);
if (!lista.length) {
  throw new Error('No hay noticias nuevas en los RSS de los últimos ' + cfg.dias + ' días.');
}

const sistema = [
  'Eres el editor de "La Bitácora", el blog de HADMIND, una empresa colombiana de software, inteligencia artificial y automatización para pymes.',
  'De la lista de noticias, elige UNA: la más útil para dueños de pequeñas y medianas empresas en Latinoamérica sobre cómo avanzan la tecnología, las apps, la IA, la automatización y el software para negocios.',
  'Prefiere: herramientas que una pyme puede usar, tendencias de adopción, cambios en plataformas que usan las empresas (WhatsApp, Google, pagos, facturación), startups y casos de negocio.',
  'Evita: rumores, lanzamientos de celulares o gadgets de consumo, videojuegos, entretenimiento, política, crimen, ofertas y noticias solo de grandes corporaciones sin utilidad para una pyme.',
].join('\n');

return [{
  json: {
    candidatas: lista,
    cuerpo: {
      model: cfg.modelo_texto,
      messages: [
        { role: 'system', content: sistema },
        { role: 'user', content: 'Noticias (indice: titulo | medio | resumen):\n' +
          lista.map((c, i) => `${i}: ${c.titulo} | ${c.medio} | ${c.resumen}`).join('\n') },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: {
          name: 'eleccion',
          strict: true,
          schema: {
            type: 'object',
            properties: {
              indice: { type: 'integer', description: 'Índice de la noticia elegida' },
              motivo: { type: 'string', description: 'Por qué es útil para una pyme, en una frase' },
            },
            required: ['indice', 'motivo'],
            additionalProperties: false,
          },
        },
      },
    },
  },
}];

// La IA devuelve un índice; la URL y el medio salen de la lista, no de la IA
// (así no puede inventar un enlace).
const { candidatas } = $('Elegir candidatas').first().json;
const respuesta = JSON.parse($json.choices[0].message.content);
const elegida = candidatas[respuesta.indice];
if (!elegida) throw new Error('La IA eligió un índice que no existe: ' + respuesta.indice);
return [{ json: { elegida, motivo: respuesta.motivo } }];

// Saca el texto de la página de la noticia (los párrafos <p>) para que la IA
// escriba con datos reales y no solo con el resumen corto del RSS.
const cfg = $('Configuración').first().json;
const { elegida } = $('Leer elección').first().json;

const entidades = { '&nbsp;': ' ', '&amp;': '&', '&quot;': '"', '&#039;': "'", '&apos;': "'",
  '&lt;': '<', '&gt;': '>', '&rsquo;': '’', '&lsquo;': '‘', '&ldquo;': '“', '&rdquo;': '”',
  '&ndash;': '–', '&mdash;': '—', '&hellip;': '…' };
const decodificar = (t) => t
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
  .replace(/&[a-z]+;|&#0?39;/gi, (e) => entidades[e] || e);

const html = String($json.data || '')
  .replace(/<(script|style|noscript|nav|header|footer|aside|form|figure)[\s\S]*?<\/\1>/gi, ' ');
const parrafos = [...html.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)]
  .map((m) => decodificar(m[1].replace(/<[^>]+>/g, '')).replace(/\s+/g, ' ').trim())
  .filter((t) => t.length > 60);

let texto = parrafos.join('\n\n').slice(0, 9000);
// Si la página no se pudo leer (bloqueo, error), se usa el resumen del RSS
if (texto.length < 400) texto = elegida.resumen;

const categorias = ['inteligencia_artificial', 'automatizacion', 'software', 'startups', 'pymes'];
const sistema = [
  'Eres el editor de "La Bitácora", el blog de HADMIND (software, IA y automatización para pymes en Colombia y Latinoamérica).',
  'Escribe un artículo ORIGINAL en español neutro (Colombia) a partir de la noticia. No copies frases de la fuente: explícala con tus palabras.',
  'Público: dueños y gerentes de pymes, sin conocimientos técnicos. Tono claro, cercano y práctico, sin exagerar.',
  'Formato del contenido en Markdown, 350 a 550 palabras:',
  '- Un párrafo de entrada (sin título).',
  '- "## Qué pasó": los hechos de la noticia.',
  '- "## Por qué importa para las pymes".',
  '- "## Qué puedes hacer": 3 o 4 viñetas concretas.',
  'Reglas: NO inventes cifras, fechas, nombres ni citas que no estén en el texto. Si un dato no está, no lo pongas.',
  'No pongas el título dentro del contenido, ni enlaces, ni emojis. No menciones a HADMIND ni hagas publicidad.',
  'titulo: máximo 90 caracteres, claro, sin clickbait, sin comillas.',
  'resumen: 1 o 2 frases, máximo 260 caracteres.',
  'categoria: una de ' + categorias.join(', ') + '.',
  'imagen_alt: describe la imagen en español, máximo 120 caracteres.',
  'prompt_imagen: en inglés, describe SOLO la escena de una ilustración que represente el tema con objetos concretos ' +
    '(sin estilo ni colores, eso se añade aparte). Sin texto, sin logos, sin marcas, sin personas reales.',
].join('\n');

return [{
  json: {
    elegida,
    cuerpo: {
      model: cfg.modelo_texto,
      messages: [
        { role: 'system', content: sistema },
        { role: 'user', content: `Noticia: ${elegida.titulo}\nMedio: ${elegida.medio}\n\nTexto:\n${texto}` },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: {
          name: 'articulo',
          strict: true,
          schema: {
            type: 'object',
            properties: {
              titulo: { type: 'string' },
              categoria: { type: 'string', enum: categorias },
              resumen: { type: 'string' },
              contenido: { type: 'string' },
              imagen_alt: { type: 'string' },
              prompt_imagen: { type: 'string' },
            },
            required: ['titulo', 'categoria', 'resumen', 'contenido', 'imagen_alt', 'prompt_imagen'],
            additionalProperties: false,
          },
        },
      },
    },
  },
}];

// Junta el artículo de la IA con la fuente y prepara el pedido de la imagen:
// estilo HADMIND fijo + la escena que propuso la IA.
const cfg = $('Configuración').first().json;
const { elegida } = $('Extraer texto').first().json;
const a = JSON.parse($json.choices[0].message.content);
const prompt = cfg.estilo_imagen + '\n\nScene: ' + a.prompt_imagen;

return [{
  json: {
    articulo: {
      titulo: a.titulo.slice(0, 200),
      categoria: a.categoria,
      resumen: a.resumen.slice(0, 400),
      contenido: a.contenido,
      imagen_alt: a.imagen_alt.slice(0, 200),
      prompt_imagen: prompt,
      fuente_nombre: elegida.medio,
      fuente_url: elegida.url,
    },
    pedido_imagen: {
      model: cfg.modelo_imagen,
      prompt,
      size: '1536x1024',
      quality: cfg.calidad_imagen,
      output_format: 'jpeg',
      n: 1,
    },
  },
}];

// OpenAI devuelve la imagen en base64: se convierte en archivo para enviarla.
const { articulo } = $('Leer artículo').first().json;
const base64 = $json.data[0].b64_json;
// Formato de archivo de n8n: los datos en base64 + tipo y nombre
const archivo = { data: base64, mimeType: 'image/jpeg', fileName: 'imagen.jpg', fileExtension: 'jpg' };
return [{ json: articulo, binary: { imagen: archivo } }];
